#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
uniform shader backdrop;
float4 amzSample_compSrc(float2 uv) { return float4(backdrop.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzSample_refImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_compSrc(uv);if(tex==1) return amzSample_refImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_useLayerBelowAsRef;
uniform float amzp_strength;
uniform float amzp_chromaStrength;
uniform float amzp_preserveLuma;
uniform float amzp_matchContrast;
uniform float amzp_robustContrast;
uniform float amzp_sampleGrid;
uniform float amzp_halfSamples;
uniform float amzp_alpha;

    const float3 LUMA = float3(0.2126, 0.7152, 0.0722);

    float3 rgb2yuv(float3 c){
      float y = dot(c, LUMA);
      float u = c.b - y;
      float v = c.r - y;
      return float3(y,u,v);
    }
    float3 yuv2rgb(float3 yuv){
      float y = yuv.x; float u = yuv.y; float v = yuv.z;
      float r = v + y;
      float b = u + y;
      float g = (y - 0.2126*r - 0.0722*b) / max(0.7152, 1e-6);
      return clamp(float3(r,g,b), 0.0, 1.0);
    }

    void accumStats(float3 c, inout float3 sum, inout float3 sum2, inout float3 minv, inout float3 maxv){
      sum += c; sum2 += c*c; minv = min(minv, c); maxv = max(maxv, c);
    }

    void amzRender(){
      float2 uv = amzScreenNorm();


      float3 srcRGB = amzTexture(0, uv).rgb;


      const int MAXN = 32;
      int N = int(floor(amzp_sampleGrid + 0.5));
      N = amzIntMax(4, amzIntMin(32, N));
      bool halfFlag = (amzp_halfSamples>0.5);
      float3 sumS=float3(0.0), sum2S=float3(0.0), minS=float3(1e9), maxS=float3(-1e9);
      float3 sumR=float3(0.0), sum2R=float3(0.0), minR=float3(1e9), maxR=float3(-1e9);
      int count=0;
      for(int y=0;y<MAXN;y++){
        if(y>=N) break;
        for(int x=0;x<MAXN;x++){
          if(x>=N) break;
          if(halfFlag && mod(float(x+y),2.0)>0.5) continue;
          float2 p=(float2(float(x)+0.5,float(y)+0.5)/float(N));
          float3 s = amzTexture(0, p).rgb;
          float3 r;
          if((amzp_useLayerBelowAsRef>0.5)){
            r = amzTexture(0, p).rgb; 
          } else {
            r = amzTexture(1, p).rgb;
          }
          accumStats(rgb2yuv(s), sumS, sum2S, minS, maxS);
          accumStats(rgb2yuv(r), sumR, sum2R, minR, maxR);
          count++;
        }
      }

      float fcount=float(count);
      float3 meanS=sumS/max(fcount,1.0);
      float3 meanR=sumR/max(fcount,1.0);
      float3 varS=max(sum2S/max(fcount,1.0)-meanS*meanS, float3(0.0));
      float3 varR=max(sum2R/max(fcount,1.0)-meanR*meanR, float3(0.0));
      float3 stdS=sqrt(varS+float3(1e-6));
      float3 stdR=sqrt(varR+float3(1e-6));

      float3 yuvS = rgb2yuv(srcRGB);
      float3 yuv = yuvS;

      if((amzp_matchContrast>0.5)){
        float yMinS = (amzp_robustContrast>0.5) ? (meanS.x - 2.0*stdS.x) : minS.x;
        float yMaxS = (amzp_robustContrast>0.5) ? (meanS.x + 2.0*stdS.x) : maxS.x;
        float yMinR = (amzp_robustContrast>0.5) ? (meanR.x - 2.0*stdR.x) : minR.x;
        float yMaxR = (amzp_robustContrast>0.5) ? (meanR.x + 2.0*stdR.x) : maxR.x;
        float yNorm=(yuv.x - yMinS)/max(yMaxS - yMinS, 1e-5);
        float yMatched=mix(yMinR, yMaxR, clamp(yNorm,0.0,1.0));
        yuv.x = mix(yuv.x, yMatched, 0.7);
      }

      float3 z=(yuv - meanS)/stdS;
      float3 yuvT=z*stdR + meanR;
      if((amzp_preserveLuma>0.5)){ yuvT.x = yuvS.x; }
      yuvT.yz = mix(yuvS.yz, yuvT.yz, amzp_chromaStrength);

      float3 cMatch = yuv2rgb(yuvT);
      float3 outRGB = mix(srcRGB, cMatch, amzp_strength);

      amzOutput = float4(outRGB, 1.0) * amzp_alpha;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

